import { Table, GuidColumn, BooleanColumn, IntegerColumn } from '../../db'

export const dl_matcher = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'order',
    extends: 'sys_metadata',
    extensible: true,
    label: 'Data Lookup Matcher Rules',
    name: 'dl_matcher',
    schema: {
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                },
            ],
            primary: true,
        }),
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Specifies whether or not this data lookup rule should be used.',
                    label: 'Active',
                    plural: 'Active',
                },
            ],
        }),
        order: IntegerColumn({
            default: '100',
            label: [
                {
                    hint: 'For matching conditions a lower order is matched against first.',
                    label: 'Order',
                    plural: 'Orders',
                },
            ],
        }),
    },
})
